Deno.serve(async () => {
  const supa = createClient(
    Deno.env.get('SUPABASE_URL')!,
    Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!
  );
  // 1) Insert retailers in batches with ON CONFLICT-equivalent via upsert ignoreDuplicates
  const batch = 100;
  let inserted = 0;
  for (let i = 0; i < ROWS.length; i += batch) {
    const chunk = ROWS.slice(i, i + batch);
    const { error, count } = await supa
      .from('retailers')
      .upsert(chunk, { onConflict: 'id', ignoreDuplicates: true, count: 'exact' });
    if (error) {
      return new Response(JSON.stringify({ step: 'insert', i, error: error.message }), { status: 500 });
    }
    inserted += (count ?? 0);
  }

  // 2) Relink orphan orders by exact retailer_name (only when match is unique)
  const { data: relinkData, error: relinkErr } = await supa.rpc('exec_sql_restore_sardar_relink');
  // Fallback if RPC missing: do it inline via two queries
  let relinked = 0;
  if (relinkErr) {
    const { data: orders, error: ordErr } = await supa
      .from('orders')
      .select('id, retailer_name')
      .eq('user_id', SARDAR)
      .is('retailer_id', null)
      .limit(2000);
    if (ordErr) return new Response(JSON.stringify({ step: 'orders_fetch', error: ordErr.message }), { status: 500 });

    const { data: rets, error: retErr } = await supa
      .from('retailers')
      .select('id, name')
      .eq('user_id', SARDAR);
    if (retErr) return new Response(JSON.stringify({ step: 'retailers_fetch', error: retErr.message }), { status: 500 });

    const nameMap = new Map<string, string[]>();
    for (const r of rets ?? []) {
      const k = (r.name ?? '').trim().toLowerCase();
      if (!k) continue;
      const arr = nameMap.get(k) ?? [];
      arr.push(r.id);
      nameMap.set(k, arr);
    }

    for (const o of orders ?? []) {
      const k = (o.retailer_name ?? '').trim().toLowerCase();
      const arr = nameMap.get(k);
      if (arr && arr.length === 1) {
        const { error: upErr } = await supa
          .from('orders')
          .update({ retailer_id: arr[0] })
          .eq('id', o.id);
        if (!upErr) relinked++;
      }
    }
  } else {
    relinked = (relinkData as any) ?? 0;
  }

  // 3) Final counts
  const { count: sardarRetailers } = await supa
    .from('retailers').select('*', { count: 'exact', head: true })
    .eq('user_id', SARDAR);
  const { count: sardarOrders } = await supa
    .from('orders').select('*', { count: 'exact', head: true })
    .eq('user_id', SARDAR);
  const { count: sardarOrphan } = await supa
    .from('orders').select('*', { count: 'exact', head: true })
    .eq('user_id', SARDAR).is('retailer_id', null);

  return new Response(JSON.stringify({
    ok: true,
    inserted_or_existing: inserted,
    relinked,
    sardar_retailers_now: sardarRetailers,
    sardar_orders_total: sardarOrders,
    sardar_orders_still_orphan: sardarOrphan,
    snapshot_rows: ROWS.length,
  }, null, 2), { headers: { 'content-type': 'application/json' } });
});
